scwin.grid1_ongroupby = function(options) {
	options.rowNumHeader = {
		inputType: 'expression',
		expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
		align: 'left',
		colSpan: 5
	};
	options.rowNumFooter = {
		colSpan: 3
	};
	options.rowStatusFooter = {
		value: '합계'
	};
	options.groupbyFooter = [{
		inputType: 'expression',
		expression: 'SUM("col3")'
	}];
	this.groupby(options);
	return true;
};
// groupby 후 분류2 화면 값(2~16번째 tr) 이 모두 A
scwin.checkValue = function() {
	var el = document.querySelectorAll('#' + grid1.id + '_body_tbody tr>td:nth-child(2)');
	for (var i = 1; i < 16; i++) {
		if (el[i].innerText != "A") {
			return false;
		}
	}
	return true;
};
// 컬럼 필터 목록 checkbox 체크 상태
scwin.__cb = function(i) {
	return document.querySelectorAll('.w2grid_customFilter_list_listColumn_checkbox')[i].checked;
};
scwin.checkVal1 = function() {
	return scwin.checkValue() == true;
};
scwin.checkVal2 = function() {
	return scwin.__cb(0) == false;
};
scwin.checkVal3 = function() {
	return scwin.__cb(1) == false;
};
scwin.checkVal4 = function() {
	return scwin.__cb(2) == true;
};
scwin.checkVal5 = function() {
	return scwin.__cb(3) == false;
};
scwin.checkVal6 = function() {
	return scwin.__cb(4) == false;
};
